#define CPU_BENCH_NO_MAIN
#include "../reference/cpu/cpu_bench.cpp"
#include "../reference/common/dataset_cache.hpp"
#include "../common/mapped_source.hpp"
#include "../common/window_source.hpp"
#include "../common/window_tasks.hpp"
#include "../common/io_metrics.hpp"
int main(int argc,char** argv){try{
 if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}
 require(argc==8,"usage: window_cpu DATA NEW_RESULTS REPS WARMUPS descending|ascending group|chunk retain|bounded|export_bounded");fs::path data=argv[1],dir=argv[2];auto n=count(argv[3],20),warm=count(argv[4],3);std::string order=argv[5],layout=argv[6],policy=argv[7];require(n&&warm<=3&&(order=="descending"||order=="ascending")&&!fs::exists(dir),"CPU window arguments");bool release=windowed::bounded(policy,false);fs::create_directories(dir);
 auto setup_start=Clock::now();windowio::Dataset source(data);InputCase input;input.n=source.shape.n;input.l=source.shape.l;input.k=source.shape.k;input.parameters=source.shape.parameters;input.words.resize(source.input_words());std::vector<uint64_t> output(input.output_words());ComputePool pool(input,output,2);auto jobs=windowed::tasks(source.dimensions.chunks,layout,order=="ascending");
 std::ofstream setup(dir/"setup.json");setup<<std::setprecision(12)<<"{\"setup_ms\":"<<elapsed(setup_start,Clock::now())<<",\"threads\":2,\"input_heap_bytes\":"<<input.words.size()*8<<",\"output_heap_bytes\":"<<output.size()*8<<",\"shared_cache_inside_request\":true}\n";setup.close();require(bool(setup),"CPU setup write");
 std::ofstream its(dir/"iterations.csv"),chunks(dir/"chunks.csv"),res(dir/"resources.jsonl");for(auto* f:{&its,&chunks,&res})*f<<std::fixed<<std::setprecision(6);its<<"repetition,warmup,export_only,request_wall_ms,shared_validate_ms,compute_sum_ms,baby_loads,baby_BO_fills,retired_records,verified_words\n";chunks<<"repetition,warmup,job,group,chunk,pack_ms,compute_ms,verify_retire_ms,verified_words\n";std::vector<double> walls,computes;
 for(unsigned rep=0;rep<n+warm;++rep){bool w=rep<warm;auto before=streamio::Metrics::now();auto start=Clock::now();source.begin_request();auto shared=elapsed(start,Clock::now());unsigned input_baby=UINT32_MAX;double compute=0;uint64_t checked=0;std::ostringstream rows;rows<<std::fixed<<std::setprecision(6);
  try{for(unsigned i=0;i<jobs.size();++i){auto t=jobs[i];auto p=Clock::now();source.cache_baby(t.chunk);source.pack_cached(t.group,t.chunk,0,1,input.words.data(),input.words.size(),input_baby!=t.chunk);input_baby=t.chunk;auto pe=Clock::now();std::fill(output.begin(),output.end(),UINT64_MAX);auto cs=Clock::now();pool.run();auto ce=Clock::now();source.verify(t.group,t.chunk,output);source.retire_job(t.group,t.chunk,release);auto ve=Clock::now();compute+=elapsed(cs,ce);checked+=output.size();rows<<rep<<','<<w<<','<<i<<','<<t.group<<','<<t.chunk<<','<<elapsed(p,pe)<<','<<elapsed(cs,ce)<<','<<elapsed(ce,ve)<<','<<output.size()<<'\n';}source.complete_coverage();source.end_request();}catch(...){source.cancel_request();throw;}
  auto wall=elapsed(start,Clock::now());auto after=streamio::Metrics::now();require(checked==source.verified_words(),"CPU six-group coverage");require(source.baby_loads==windowed::expected_cache_counts(jobs).first,"CPU baby load coverage");require(source.baby_BO_fills==source.baby_loads,"CPU baby pack coverage");its<<rep<<','<<w<<",0,"<<wall<<','<<shared<<','<<compute<<','<<source.baby_loads<<','<<source.baby_BO_fills<<','<<source.retired_records<<','<<checked<<'\n';chunks<<rows.str();res<<"{\"repetition\":"<<rep<<",\"warmup\":"<<w<<",\"bounded_advice\":"<<release<<",\"process_metrics\":"<<after.delta_json(before)<<"}\n";for(auto* f:{&its,&chunks,&res}){f->flush();require(bool(*f),"CPU CSV write");}if(!w){walls.push_back(wall);computes.push_back(compute);}std::cout<<"PASS_WINDOW_CPU_SIX_GROUPS repetition="<<rep<<" warmup="<<w<<" request_wall_ms="<<wall<<" compute_sum_ms="<<compute<<" verified_words="<<checked<<'\n'<<std::flush;
 }
 std::ofstream summary(dir/"summary.json");summary<<std::setprecision(12)<<"{\"status\":\"PASS_WINDOW_CPU_SIX_GROUPS\",\"execution_backend\":\"ARM_CPU_2_THREADS\",\"AIE_compute_tiles\":0,\"measured\":"<<n<<",\"warmups\":"<<warm<<",\"request_wall_median_ms\":"<<med(walls)<<",\"compute_sum_median_ms\":"<<med(computes)<<",\"layout\":\""<<layout<<"\",\"cache_policy\":\""<<policy<<"\",\"scope\":\"Identical source, job order, shared validation, bounded advice policy and full verification; unchanged historical two-thread u128 math. Not full OpenFHE layer or optimal-CPU claim.\"}\n";summary.close();require(bool(summary),"CPU summary write");return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
